const f=c=>c==="photo_3x4"?{w:.8,aspect:.75}:{w:.9,aspect:1.585},v=(c,a,e,o={})=>{const r=f(c),x=o.widthRatio??r.w,h=o.maxWidthRatio??.98,i=o.maxHeightRatio??.9,l=o.centerYOffset??0;let s=Math.min(a*x,a*h),t=s/r.aspect;const n=e*i;t>n&&(t=n,s=t*r.aspect);const m=(a-s)/2,w=(e-t)/2+e*l,R=Math.max(0,Math.min(w,e-t));return{overlayWidth:s,overlayHeight:t,overlayX:m,overlayY:R}};export{f as a,v as g};
